fn count_occurrences(xs: List[Int], x: Int) -> Int
  requires len(xs) >= 0
  ensures result >= 0 and result == count(xs, x)
  effects pure
  example count_occurrences([1, 2, 2, 3], 2) == 2
  example count_occurrences([], 1) == 0
  example count_occurrences([1, 1, 1], 1) == 3
{
  match xs {
    [] => 0
    [h, ..t] =>
      if h == x
      then 1 + count_occurrences(t, x)
      else count_occurrences(t, x)
  }
}

fn is_more_frequent(xs: List[Int], a: Int, b: Option[Int]) -> Bool
  requires contains(xs, a)
  requires match b {
    None => true
    Some(b_val) => contains(xs, b_val)
  }
  ensures match b {
    None => result == true
    Some(b_val) => result == (count(xs, a) > count(xs, b_val))
  }
  effects pure
  example is_more_frequent([1, 2, 2, 3], 2, None) == true
  example is_more_frequent([1, 2, 2, 3], 1, Some(2)) == false
  example is_more_frequent([1, 2, 2, 3], 2, Some(1)) == true
{
  match b {
    None => true
    Some(b_val) => count_occurrences(xs, a) > count_occurrences(xs, b_val)
  }
}

fn find_max_helper(original: List[Int], remaining: List[Int], best: Option[Int]) -> Option[Int]
  requires forall c in remaining: contains(original, c)
  requires match best {
    None => true
    Some(b) => contains(original, b)
  }
  ensures match result {
    None => len(original) == 0
    Some(x) => contains(original, x) and forall y in original: y == x or count(original, x) > count(original, y)
  }
  effects pure
  example find_max_helper([1, 2, 2, 3], [1, 2, 3], None) == Some(2)
  example find_max_helper([], [], None) == None
  example find_max_helper([5], [5], None) == Some(5)
{
  match remaining {
    [] => best
    [h, ..t] =>
      if is_more_frequent(original, h, best)
      then find_max_helper(original, t, Some(h))
      else find_max_helper(original, t, best)
  }
}

fn most_frequent(xs: List[Int]) -> Option[Int]
  requires len(xs) == 0 or exists x in xs: forall y in xs: y == x or count(xs, x) > count(xs, y)
  ensures match result {
    None => len(xs) == 0
    Some(x) => contains(xs, x) and forall y in xs: y == x or count(xs, x) > count(xs, y)
  }
  effects pure
  example most_frequent([]) == None
  example most_frequent([1, 2, 2, 3]) == Some(2)
  example most_frequent([5]) == Some(5)
{
  find_max_helper(xs, xs, None)
}

