fn nth(xs: List[Int], i: Int) -> Option[Int]
  requires i >= 0
  ensures (i < len(xs)) or (result == None)
  ensures (i >= len(xs)) or (result != None)
  effects pure
  example nth([5, 6, 7], 1) == Some(6)
  example nth([5, 6, 7], 3) == None
  example nth([], 0) == None
  example nth([42], 0) == Some(42)
  example nth([1, 2, 3], 0) == Some(1)
{
  if i == 0 then match xs {
    [] => None
    [h, ..t] => Some(h)
  } else match xs {
    [] => None
    [_, ..t] => nth(t, i - 1)
  }
}

